mapper.select:
select a.* from (select ROW_NUMBER() OVER (order by reg_dt) AS row, * from om_insp_log oil where 1=1 and reg_dt between to_timestamp(#{search_from}, 'YYYY-MM-DD HH24:MI:SS') and to_timestamp(#{search_to}, 'YYYY-MM-DD HH24:MI:SS')
and lgn_id like concat('%',#{searchKeyword},'%')
order by insp_log_sn desc)a LIMIT 10 OFFSET #{offset}
